// And groups predicates with the AND operator between them.
func And(predicates ...predicate.QuestionPaper) predicate.QuestionPaper {
	return predicate.QuestionPaper(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.QuestionPaper) predicate.QuestionPaper {
	return predicate.QuestionPaper(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.QuestionPaper) predicate.QuestionPaper {
	return predicate.QuestionPaper(sql.NotPredicates(p))
}
